        "Глава I („Гост“): Семейната вечеря в дома на чорбаджи Марко олицетворява патриархалния космос, реда, набожността и уважението към учението. Внезапната буря и появата на беглеца от Диарбекир Иван Кралича бележат нахлуването на историята и бунта в мирния бит.",
        "Образът на чорбаджи Марко: Праведен родолюбец и баща, който въпреки своята трезва предпазливост помага на революционера и по-късно изрича крилатата фраза „Лудите, лудите — те да са живи!“.",
        "Глава XI („Годишният изпит“ / „Радини вълнения“): На празника на св. св. Кирил и Методий сирачето учителка Рада Госпожина е подложена на публично унижение от чорбаджийския син и туркофил Кириак Стефчов.",
