    "originalNoteExcerpt": "Рационални числа (положителни, отрицателни и 0). Координатна ос. Противоположни числа (a и -a, сбор 0). Модул (абсолютна стойност) |a| >= 0 (разстояние до 0). Събиране и изваждане на рационални числа. Знакови правила при умножение и деление: (-).(-) = (+), (-).(+) = (-). Степени: a^m . a^n = a^(m+n); a^m : a^n = a^(m-n); (a^m)^n = a^(m.n); a^0 = 1, a^(-n) = 1/a^n.",
