    "originalNoteExcerpt": "Съединение (6 септември 1885 г., Пловдив): БТЦРК начело със Захари Стоянов („Борба“), майор Данаил Николаев, Чардафон Велики, сваляне на ген.-губернатора Гаврил Кръстевич. Княз Александър I Батенберг признава Съединението на 8 септ. Сръбско-българска война (ноември 1885 г., „Войната на капитаните срещу генералите“, Сливница, Гургулят, Пирот). Топханенски акт (24 март 1886 г.). Независимост (22 септември 1908 г., В. Търново, църква „Св. 40 мъченици“, цар Фердинанд, премиер Александър Малинов).",
